#!/usr/bin/env python3
"""eam-wo-cost-50 (PRD 8.44 fixtures): 50 work orders on 5 assets with labor
bookings and parts costs, and the expected cost roll-ups.

Run with `python3 -I gen_wo_cost_50.py` from this directory; it writes
fixture.json and expected.json. Expected amounts use decimal.Decimal and share
no code with the Go engine.

* Labor line cost = hours x rate rounded to the cent (FR-44.10). The PRD has
  two rounding modes for money (FR-6.16 half_even default, FR-12.6 half away
  from zero), so the generator leaves out exact half-cent products: every line
  here rounds the same way under either mode.
* Parts cost is the order's issued parts value (wave-16 part issue is not
  built; the test writes it on the order as the issue would).
* Work order 1 is AC-44.3: 350.00 parts and 8 h at 45.00 = 710.00.
* Orders complete on a day of 2026; the cost KPI window is [2026-02-01,
  2026-12-01), so orders completed in January or December fall outside it.
"""

import json
from decimal import Decimal, ROUND_HALF_EVEN, ROUND_HALF_UP

CENT = Decimal("0.01")


def lcg(seed):
    while True:
        seed = (seed * 1103515245 + 12345) % (2 ** 31)
        yield seed


def main():
    rnd = lcg(4403)
    assets = ["PUMP-1", "PUMP-2", "FAN-1", "PRESS-1", "PRESS-2"]
    orders = [{"asset": "PUMP-1", "completedOn": "2026-10-21", "parts": "350.00",
               "labor": [{"hours": "8", "rate": "45.00"}]}]
    while len(orders) < 50:
        asset = assets[next(rnd) % len(assets)]
        month = 1 + next(rnd) % 12
        day = 1 + next(rnd) % 28
        lines = []
        for _ in range(next(rnd) % 4):  # 0 to 3 labor lines
            while True:
                q = 1 + next(rnd) % 48             # 0.25 h to 12 h in quarter hours
                c = 3500 + next(rnd) % 6500        # 35.00 to 99.99 per hour
                if (q * c) % 4 != 2:               # no exact half cent
                    break
            lines.append({"hours": str(Decimal(q) / 4), "rate": str(Decimal(c) / 100)})
        parts = Decimal(next(rnd) % 120000) / 100 if next(rnd) % 3 else Decimal("0.00")
        orders.append({"asset": asset, "completedOn": f"2026-{month:02d}-{day:02d}",
                       "parts": str(parts.quantize(CENT)), "labor": lines})

    def labor_cost(line):
        exact = Decimal(line["hours"]) * Decimal(line["rate"])
        even = exact.quantize(CENT, rounding=ROUND_HALF_EVEN)
        assert even == exact.quantize(CENT, rounding=ROUND_HALF_UP), line
        return even

    per_asset = {a: {"parts": Decimal(0), "labor": Decimal(0), "windowParts": Decimal(0),
                     "windowLabor": Decimal(0), "windowOrders": 0} for a in assets}
    per_order = []
    for o in orders:
        labor = sum((labor_cost(l) for l in o["labor"]), Decimal(0))
        parts = Decimal(o["parts"])
        per_order.append({"parts": str(parts.quantize(CENT)), "labor": str(labor.quantize(CENT)),
                          "total": str((parts + labor).quantize(CENT))})
        s = per_asset[o["asset"]]
        s["parts"] += parts
        s["labor"] += labor
        if "2026-02-01" <= o["completedOn"] < "2026-12-01":
            s["windowParts"] += parts
            s["windowLabor"] += labor
            s["windowOrders"] += 1

    assert per_order[0] == {"parts": "350.00", "labor": "360.00", "total": "710.00"}

    expected = {
        "comment": "Generated by gen_wo_cost_50.py (python3 -I); do not edit by hand.",
        "window": {"from": "2026-02-01T00:00:00Z", "to": "2026-12-01T00:00:00Z"},
        "orders": per_order,
        "assets": {a: {k: (str(v.quantize(CENT)) if isinstance(v, Decimal) else v) for k, v in s.items()}
                   for a, s in per_asset.items()},
        "grandTotal": str(sum((s["parts"] + s["labor"] for s in per_asset.values()), Decimal(0)).quantize(CENT)),
    }
    with open("fixture.json", "w") as f:
        json.dump({"comment": "Generated by gen_wo_cost_50.py; see its docstring.", "assets": assets,
                   "orders": orders}, f, indent=1)
        f.write("\n")
    with open("expected.json", "w") as f:
        json.dump(expected, f, indent=1, sort_keys=True)
        f.write("\n")
    print(f"{len(orders)} orders, {sum(len(o['labor']) for o in orders)} labor lines, total {expected['grandTotal']}")


if __name__ == "__main__":
    main()
